package hn.uth.pm1ea0199.controller;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.graphics.Color;import android.view.Gravity;import android.widget.*;import hn.uth.pm1ea0199.dao.ContactoDAO;import hn.uth.pm1ea0199.model.Contacto;import hn.uth.pm1ea0199.view.Vistas;
public class LlamarActivity extends Activity {
 private Contacto c;
 @Override public void onCreate(Bundle s){super.onCreate(s);ContactoDAO dao=new ContactoDAO(this);try{c=dao.buscar(getIntent().getLongExtra("id",-1));}finally{dao.close();}if(c==null){finish();return;}LinearLayout l=Vistas.pagina(this,"");setContentView(l);Button atras=Vistas.boton(this,l,"Atrás   ...");LinearLayout.LayoutParams al=(LinearLayout.LayoutParams)atras.getLayoutParams();al.width=Vistas.dp(this,90);atras.setLayoutParams(al);atras.setOnClickListener(v->finish());TextView nombre=new TextView(this);nombre.setText(c.nombre);nombre.setTextSize(20);nombre.setTypeface(null,1);nombre.setGravity(Gravity.CENTER);nombre.setTextColor(Color.BLACK);nombre.setPadding(0,18,0,4);l.addView(nombre);TextView numero=new TextView(this);numero.setText(Vistas.numeroVisible(c.pais,c.telefono));numero.setTextSize(29);numero.setTypeface(null,1);numero.setGravity(Gravity.CENTER);numero.setTextColor(Color.BLACK);l.addView(numero);android.view.View espacio=new android.view.View(this);l.addView(espacio,new LinearLayout.LayoutParams(-1,0,1));Button llamar=Vistas.boton(this,l,"☎");llamar.setContentDescription("Llamar al contacto");llamar.setTextSize(36);llamar.setTextColor(Color.WHITE);llamar.setBackground(Vistas.fondo(Color.rgb(54,172,100),Color.rgb(54,172,100),100));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(Vistas.dp(this,70),Vistas.dp(this,70));lp.gravity=Gravity.CENTER_HORIZONTAL;lp.setMargins(0,0,0,25);llamar.setLayoutParams(lp);llamar.setOnClickListener(v->confirmar());if(s==null&&getIntent().getBooleanExtra("confirmada",false))pedirPermiso();}
 private void confirmar(){new AlertDialog.Builder(this).setTitle("Acción").setMessage("¿Desea llamar a "+c.nombre+"?").setNegativeButton("No",null).setPositiveButton("Sí",(d,w)->pedirPermiso()).show();}
 private void pedirPermiso(){if(checkSelfPermission(Manifest.permission.CALL_PHONE)==PackageManager.PERMISSION_GRANTED)llamar();else requestPermissions(new String[]{Manifest.permission.CALL_PHONE},20);}
 private void llamar(){try{startActivity(new Intent(Intent.ACTION_CALL,Uri.fromParts("tel",Vistas.numero(c.pais,c.telefono),null)));}catch(SecurityException e){Vistas.alerta(this,"Se necesita el permiso de llamadas.");}catch(ActivityNotFoundException e){Vistas.alerta(this,"Este dispositivo no permite realizar llamadas. Prueba en un teléfono con SIM.");}}
 @Override public void onRequestPermissionsResult(int r,String[] permisos,int[] resultados){super.onRequestPermissionsResult(r,permisos,resultados);if(r==20){if(resultados.length>0&&resultados[0]==PackageManager.PERMISSION_GRANTED)llamar();else Vistas.alerta(this,"Permiso denegado. Puedes autorizarlo en Ajustes > Aplicaciones > Agenda de Contactos > Permisos.");}}
}
